def climate(tmp_path):
    path=tmp_path/'fictional-climate.csv'
    prefix=climate_bytes().split(b'2024-02-04')[0]
    path.write_bytes(prefix+b''.join(f'{date(2024,2,4)+timedelta(days=i)},25,15,20,45,1\n'.encode() for i in range(56)))
    return path


def test_complementary_ingest_transaction_idempotency_withdrawal_and_receipts(db,tmp_path):
    path=climate(tmp_path);sha=hashlib.sha256(path.read_bytes()).hexdigest()
    kwargs=dict(expected_sha256=sha,version='fictional-1',authorization_ref='FICTIONAL AUTHORIZATION')
    first=import_complement(db,path,OpenMeteoCSV(),**kwargs)
    second=import_complement(db,path,OpenMeteoCSV(),**kwargs)
    assert first['status']=='imported' and second['status']=='already_imported'
    with db.cursor() as c:
        c.execute('SELECT count(*) FROM epidemiology.clima_diario');assert c.fetchone()[0]==56
        c.execute('SELECT count(*) FROM ingestion.fila_complementaria');assert c.fetchone()[0]==56
        c.execute('SELECT filas_aceptadas FROM ingestion.lote_complementario');assert c.fetchone()[0]==56
    with pytest.raises(ValueError):
        import_complement(db,path,OpenMeteoCSV(),**(kwargs|dict(version='fictional-rollback')),fail_after=1)
    with db.cursor() as c:
        c.execute('SELECT count(*) FROM ingestion.lote_complementario');assert c.fetchone()[0]==1
        c.execute("SELECT count(*) FROM ingestion.intento_complementario WHERE estado='failed'");assert c.fetchone()[0]==1
    withdraw(db,first['batch_id'],reason='FICTIONAL withdrawal')
    with pytest.raises(ValueError):import_complement(db,path,OpenMeteoCSV(),**kwargs)
    with db.cursor() as c:
        c.execute('SELECT count(*) FROM ingestion.lotes_complementarios_vigentes');assert c.fetchone()[0]==0
        c.execute('SELECT count(*) FROM epidemiology.clima_diario');assert c.fetchone()[0]==56


def test_reconstruction_never_reads_excel_or_csv_and_preserves_unknowns(db,tmp_path,monkeypatch):
    path=climate(tmp_path)
    loaded=import_complement(db,path,OpenMeteoCSV(),expected_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),version='fictional-c',authorization_ref='FICTIONAL')
    source=tmp_path/'fictional.xlsx';book=Workbook();ws=book.active
    ws.append(['Id Evento caso','Clasificacion manual del caso','Fecha de inicio de sintomas',
        'Pais de residencia','Provincia de residencia','Departamento de residencia','Localidad de residencia'])
    ws.append(['FICTIONAL-1','Confirmado',date(2024,2,4),'argentina','la rioja','capital','la rioja'])
    ws.append(['FICTIONAL-2','Confirmado',None,'argentina','la rioja','capital','la rioja'])
    book.save(source);import_book(db,source)
    resolve(db,version='fictional-r',evidence={'ref':'FICTIONAL REVIEW'})
    with db.cursor() as c:c.execute('SELECT id FROM ingestion.lote_importacion');bid=c.fetchone()[0]
    def forbidden(*args,**kwargs):raise AssertionError('training reconstruction attempted file IO')
    monkeypatch.setattr(Path,'open',forbidden)
    import pandas as pd
    import openpyxl
    monkeypatch.setattr(pd,'read_csv',forbidden);monkeypatch.setattr(pd,'read_parquet',forbidden)
    monkeypatch.setattr(openpyxl,'load_workbook',forbidden)
    result=materialize_dataset(db,version='fictional-dataset',resolution_version='fictional-r',batch_ids=[bid],
        climate_batch_id=loaded['batch_id'],covered_weeks=[date(2024,2,4),date(2024,2,11)],authorization_ref='FICTIONAL')
    assert result['included_records']==1 and result['exclusions']['missing_clinical_reference_date']==1
    frame=read_series(db,'fictional-dataset')
    assert frame.conteo_conservador.isna().all()
    assert frame.loc[frame.inicio.eq(date(2024,2,11))].iloc[0].conteo_experimental==0
    assert pd.isna(frame.loc[frame.inicio.eq(date(2024,2,18))].iloc[0].conteo_experimental)
    assert frame.loc[frame.inicio.eq(date(2024,2,4))].iloc[0].precipitacion==7
    assert infer(db,model_version='FICTIONAL_UNKNOWN',origin=date(2024,2,4))['status']=='prediction_unavailable'
    withdraw_sisa(db,bid,reason='FICTIONAL source withdrawal')
    with db.cursor() as c:
        c.execute("SELECT lotes_vigentes FROM analytics.disponibilidad_dataset_predictivo WHERE version='fictional-dataset'")
        assert not c.fetchone()[0]
        c.execute('SELECT count(*) FROM epidemiology.registro_epidemiologico');assert c.fetchone()[0]==2


def test_new_private_tables_reject_public_and_reader_individual_access(db):
    with db.cursor() as c:
        for table in ['ingestion.fila_complementaria','ingestion.intento_complementario','analytics.seleccion_registro_predictivo']:
            c.execute("SELECT has_table_privilege('sigard_epi_analytics_reader',%s,'SELECT')",(table,))
            assert not c.fetchone()[0]
        c.execute("SET ROLE sigard_epi_analytics_reader")
        c.execute('SELECT count(*) FROM analytics.serie_predictiva_lectura')
        assert c.fetchone()[0]==0
    db.rollback()


def test_db_only_training_registration_inference_and_single_version(db,monkeypatch):
    from psycopg2.extras import Json,execute_values
    from sigard_ml.ingestion.epidemiology.analytics import seed_policies
    from sigard_ml.official.calendar_rules import CALENDAR_VERSION
    from sigard_ml.forecasting.core_data import canonical_hash
    from sigard_ml.forecasting.core_model import train_and_register,PROTOCOL
    import pandas as pd
    import openpyxl
    seed_policies(db)
    with db:
        with db.cursor() as c:
            c.execute("INSERT INTO epidemiology.version_resolucion(version,politica,entrada_sha256,evidencia) VALUES('FICTIONAL-R','FICTIONAL',%s,'{}')",('a'*64,))
            c.execute("INSERT INTO analytics.dataset_predictivo VALUES('FICTIONAL-D',%s,%s,%s,'FICTIONAL-R','capital_source_residence',now())",(Json({'fixture':True}),'b'*64,CALENDAR_VERSION))
            c.execute('SELECT id,inicio,numero,anio FROM analytics.semana_epidemiologica WHERE calendario_version=%s ORDER BY inicio',(CALENDAR_VERSION,))
            weekly=c.fetchall()
            counts=[];weather=[]
            for wid,w,number,year in weekly:
                known=year in (2020,2021,2023,2024) and 6<=number<=35
                count=2+number%4 if known else None
                counts.append(('FICTIONAL-D',wid,'capital',count or 0,None,count,'experimental_assumed' if known else 'out_of_scope',0,0,None,False))
                weather.append(('FICTIONAL-D',wid,20.,45.,7.,7,None))
            execute_values(c,'INSERT INTO analytics.serie_predictiva VALUES %s',counts)
            execute_values(c,'INSERT INTO analytics.clima_predictivo VALUES %s',weather)
    def forbidden(*args,**kwargs):raise AssertionError('tabular source reopened')
    monkeypatch.setattr(pd,'read_csv',forbidden);monkeypatch.setattr(pd,'read_parquet',forbidden)
    monkeypatch.setattr(openpyxl,'load_workbook',forbidden)
    result,_,panel,_=train_and_register(db,dataset_version='FICTIONAL-D',model_version='FICTIONAL-M',protocol_sha256=canonical_hash(PROTOCOL))
    assert result['report']['independent_test'] is False
    assert result['report']['periods']['2024']['train_last_target_end']<'2024-01-01'
    latest=max(panel.loc[panel.admissible&panel.target_count.notna()].target_week)
    actual=infer(db,model_version='FICTIONAL-M',origin=latest,mode='retrospective')
    assert actual['probability'] is None and actual['relative_activity'] is None
    assert actual['status'] in ('prediction_unavailable','available_retrospective_candidate')
    current=infer(db,model_version='FICTIONAL-M',origin=date(2026,10,25))
    assert current['expected_count'] is None and 'fundamental_features_or_coverage_missing' in current['reasons']
    with pytest.raises(ValueError,match='single_candidate_already_registered'):
        train_and_register(db,dataset_version='FICTIONAL-D',model_version='FICTIONAL-SECOND',protocol_sha256=canonical_hash(PROTOCOL))
    with db.cursor() as c:
        c.execute("SET ROLE sigard_epi_analytics_reader")
    allowed=infer(db,model_version='FICTIONAL-M',origin=date(2026,10,25))
    assert allowed['status']=='prediction_unavailable'
    with db.cursor() as c:c.execute('RESET ROLE')
